import os
import sys
import subprocess
import re

def parse_token_file(token_file_path):
    with open(token_file_path, 'r') as f:
        line = f.readline().strip()
    if not line:
        print("AUTH_FAILED")
        sys.exit(1)
    token, allowed_commands = line.split(':', 1)
    return token, allowed_commands.split(',')

def main():
    if len(sys.argv) != 4 or sys.argv[1] != '--token-file' or sys.argv[3] != '--commands-file':
        print("Usage: python authed_run.py --token-file <path> --commands-file <path>")
        sys.exit(1)

    token_file = sys.argv[2]
    commands_file = sys.argv[4]

    provided_token = os.getenv('RUNNER_TOKEN')
    if not provided_token:
        print("AUTH_FAILED")
        sys.exit(1)

    token, allowed_commands = parse_token_file(token_file)
    if token != provided_token:
        print("AUTH_FAILED")
        sys.exit(1)

    with open(commands_file, 'r') as f:
        commands = [cmd.strip() for cmd in f.readlines() if cmd.strip()]

    for cmd in commands:
        if not cmd:
            continue
        parts = cmd.split()
        if not parts:
            continue
        command_name = parts[0]
        if command_name not in allowed_commands:
            print(f"DENIED: {cmd}")
            continue

