import os
import sys
import subprocess
import re

def main():
    token_file = None
    commands_file = None

    for arg in sys.argv[1:]:
        if arg == "--token-file":
            token_file = sys.argv[sys.argv.index(arg) + 1]
        elif arg == "--commands-file":
            commands_file = sys.argv[sys.argv.index(arg) + 1]

    if not token_file or not commands_file:
        print("AUTH_FAILED")
        sys.exit(1)

    with open(token_file, 'r') as f:
        token_line = f.readline().strip()
        token, allowed_commands = token_line.split(':', 1)
        allowed_commands = set(allowed_commands.split(','))
        if token != os.getenv('RUNNER_TOKEN'):
            print("AUTH_FAILED")
            sys.exit(1)

    with open(commands_file, 'r') as f:
        commands = [line.strip() for line in f if line.strip()]

    for cmd in commands:
        if not cmd:
            continue
        cmd_parts = cmd.split(maxsplit=1)
        if len(cmd_parts) < 1:
            continue
        command_name = cmd_parts[0]
        if command_name not in allowed_commands:
            print(f"DENIED: {cmd}")
            continue

        try:
            result = subprocess.run(cmd, shell=True, check=False, text=True, capture_output=True)
            if result.stdout:
                for line in result.stdout.splitlines():
                    print(f"OUT: {line}")
            if result.stderr:
                for line in result.stderr.splitlines():
                    print(f"ERR: {line}")
            if result.returncode != 0:
                print(f"EXIT: {result.returncode}")
        except Exception:
            continue

    if any(result.returncode != 0 for result in subprocess.run(cmd, shell=True, check=False, text=True, capture_output=True, capture_output=True for cmd in commands if cmd.split(maxsplit=1)[0] in allowed_commands)):
        sys.exit(2)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()
